withinTransaction(async () => {
  const trackCount = song.get("tracks.length");
  await song.call("createMidiTrack", "after", song.get(`tracks.${trackCount - 1}.id`));
  await song.call("createMidiTrack", "after", song.get(`tracks.${trackCount}.id`));

  const tracks = song.get("tracks");
  tracks[1].set("name", "Kick");
  tracks[2].set("name", "Bass");
  tracks[3].set("name", "Drums");
  tracks[4].set("name", "Chords");
  tracks[5].set("name", "Pads");
});

